-- Specialised MCQ items (civil_supervisor): gas-transmission pipelines, PRS/CGS, CP, metering and compressor stations. Sources are named in standard_ref.
-- Added 2026-10-15; approved by owner instruction (no manual review).
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref, approval_status, active)
select v.job_role, 'TECHNICAL', v.topic, v.difficulty, v.stem_fa, v.options, v.correct_option, v.item_type, v.answer_key, v.explanation_fa, v.standard_ref, 'APPROVED', true
from (values
  ('civil_supervisor', 'بتن در محیط سولفاتی', 2, 'حداکثر نسبت آب به مواد سیمانی (w/cm) برای بتن در معرض سولفات شدید (کلاس S3) طبق ACI 318 چقدر است؟', '["حدود ۰٫۴۵","حدود ۰٫۶۵","حدود ۰٫۷۵","حدود ۰٫۵۵"]'::jsonb, 0, 'SINGLE', null, 'ACI 318: در تماس با سولفات متوسط تا شدید (S2 و S3) حداکثر w/cm برابر ۰٫۴۵ است و سیمان مقاوم به سولفات (نوع V یا ترکیب با پوزولان) لازم است.', 'ACI 318 (Building Code Requirements for Structural Concrete)'),
  ('civil_supervisor', 'بتن در محیط سولفاتی', 1, 'برای فونداسیون ایستگاه واقع در خاک حاوی سولفات زیاد، کدام نوع سیمان مناسب‌تر است؟', '["سیمان پرتلند نوع III (زودگیر)","سیمان پرتلند نوع V (مقاوم)","سیمان پرتلند نوع I معمولی","سیمان آلومینایی گیرش سریع"]'::jsonb, 1, 'SINGLE', null, 'سیمان نوع V (ASTM C150) مقدار C3A کم دارد و در برابر حمله سولفات مقاوم است.', 'ASTM C150'),
  ('civil_supervisor', 'پوشش بتن', 2, 'حداقل پوشش بتن روی میلگرد در فونداسیونی که مستقیماً روی خاک ریخته می‌شود و دائماً در تماس با خاک است چقدر است؟', '["۲۵ میلی‌متر","۵۰ میلی‌متر","۷۵ میلی‌متر","۱۰۰ میلی‌متر"]'::jsonb, 2, 'SINGLE', null, 'ACI 318: بتن ریخته‌شده روی خاک و دائماً در تماس با آن: حداقل پوشش ۷۵ mm (۳ in).', 'ACI 318 (Building Code Requirements for Structural Concrete)'),
  ('civil_supervisor', 'پذیرش مقاومت بتن', 3, 'معیار پذیرش مقاومت فشاری بتن طبق ACI 318 (برای f''c ≤ ۳۵ MPa) کدام است؟', '["میانگین ۳ نمونه ≥ ۰٫۸ f''c و هر نمونه ≥ ۰٫۶ f''c","هر نمونه ≥ f''c و میانگین ≥ ۱٫۲ f''c","میانگین ۷ روزه ≥ f''c و نمونهٔ ۲۸ روزه لازم نیست","میانگین ۳ نمونهٔ پیاپی ≥ f''c و هر نمونه ≥ f''c−۳٫۵"]'::jsonb, 3, 'SINGLE', null, 'پذیرش آماری ACI 318: میانگین سه آزمون متوالی برابر یا بیشتر از f''c و هیچ آزمونی کمتر از f''c − 3.5 MPa نباشد.', 'ACI 318 (Building Code Requirements for Structural Concrete)'),
  ('civil_supervisor', 'آزمون بتن تازه', 1, 'آزمون اسلامپ (ASTM C143) کدام ویژگی بتن تازه را می‌سنجد؟', '["کارایی و روانی بتن","مقاومت فشاری ۲۸ روزه","درصد هوای محبوس","دمای هیدراتاسیون"]'::jsonb, 0, 'SINGLE', null, 'اسلامپ شاخص ساده‌ای از روانی/کارایی بتن تازه است و برای کنترل یکنواختی هر محموله به‌کار می‌رود.', 'ASTM C143'),
  ('civil_supervisor', 'بتن‌ریزی در هوای گرم', 2, 'حداکثر دمای توصیه‌شده بتن هنگام ریختن در هوای گرم (ACI 305) چقدر است؟', '["حدود ۵۰°C","حدود ۳۵°C","حدود ۱۸°C","حدود ۲۵°C"]'::jsonb, 1, 'SINGLE', null, 'ACI 305R توصیه می‌کند دمای بتن هنگام ریختن از حدود ۳۵°C (۹۵°F) بیشتر نشود.', 'ACI 305R (Hot Weather Concreting)'),
  ('civil_supervisor', 'بتن‌ریزی در هوای سرد', 2, 'در هوای سرد بتن باید تا رسیدن به چه مقاومتی از یخ‌زدگی محافظت شود؟', '["حدود ۱ مگاپاسکال (۱۵۰ psi)","حدود ۱۰ مگاپاسکال (۱۴۵۰ psi)","حدود ۳٫۵ مگاپاسکال (۵۰۰ psi)","حدود ۲۸ مگاپاسکال (۴۰۰۰ psi)"]'::jsonb, 2, 'SINGLE', null, 'ACI 306: بتن تازه باید تا رسیدن مقاومت فشاری حدود ۳٫۵ MPa از یخ‌زدگی محافظت شود.', 'ACI 306R (Cold Weather Concreting)'),
  ('civil_supervisor', 'عمل‌آوری بتن', 1, 'حداقل مدت عمل‌آوری مرطوب بتن با سیمان معمولی طبق مبنای ACI چقدر است؟', '["حدود ۱ روز","حدود ۳ ساعت","حدود ۶۰ روز","حدود ۷ روز"]'::jsonb, 3, 'SINGLE', null, 'ACI 308 / 318: برای سیمان نوع I حداقل ۷ روز عمل‌آوری مرطوب (یا رسیدن به ۷۰٪ مقاومت) لازم است.', 'ACI 308R (Curing Concrete)'),
  ('civil_supervisor', 'سنگدانه', 2, 'حداکثر اندازهٔ اسمی سنگدانه نباید از چه کسری از کوچک‌ترین بعد بین قالب‌ها بیشتر شود؟', '["یک‌پنجم","یک‌دوم","دو‌سوم","سه‌چهارم"]'::jsonb, 0, 'SINGLE', null, 'ACI 318: حداکثر اندازهٔ سنگدانه ≤ ۱/۵ کوچک‌ترین بعد بین قالب‌ها، ≤ ۱/۳ ضخامت دال و ≤ ۳/۴ فاصلهٔ آزاد میلگردها.', 'ACI 318 (Building Code Requirements for Structural Concrete)'),
  ('civil_supervisor', 'طبقه‌بندی خاک USCS', 3, 'خاکی ۶۰٪ عبوری از الک ۲۰۰ دارد؛ حد روانی ۵۵٪ و شاخص خمیری ۳۰٪ است. طبق USCS (خط A: PI = 0.73(LL−20)) کدام است؟', '["CL (رس کم‌خمیری)","CH (رس پرخمیری)","MH (لای پرخمیری)","SC (ماسه رسی)"]'::jsonb, 1, 'SINGLE', null, 'ریزدانه است و LL>50؛ PI=30 بالاتر از خط A (≈25.5) ⇒ رس پرخمیری CH.', 'ASTM D2487 (USCS)'),
  ('civil_supervisor', 'طبقه‌بندی خاک USCS', 3, 'شن با ۳٪ ریزدانه، Cu=8 و Cc=1٫۵ طبق USCS چه نامی دارد؟', '["GP (شن بد دانه‌بندی‌شده)","GM (شن لای‌دار)","GW (شن خوب دانه‌بندی‌شده)","SW (ماسه خوب دانه‌بندی‌شده)"]'::jsonb, 2, 'SINGLE', null, 'کمتر از ۵٪ ریزدانه؛ Cu≥۴ و ۱≤Cc≤۳ برای شن ⇒ GW.', 'ASTM D2487 (USCS)'),
  ('civil_supervisor', 'حدود آتربرگ', 1, 'حد روانی خاکی ۴۸٪ و حد خمیری آن ۲۲٪ است. شاخص خمیری (PI) چند درصد است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"٪","value":26,"tolPct":1}'::jsonb, 'PI = LL − PL = 48 − 22 = 26', 'ASTM D4318 (Atterberg limits)'),
  ('civil_supervisor', 'تراکم خاک', 2, 'انرژی تراکم در آزمون پروکتور اصلاح‌شده (ASTM D1557) نسبت به استاندارد (ASTM D698) تقریباً چند برابر است؟', '["حدود ۱٫۵ برابر","حدود ۱۰ برابر","حدود ۲۰ برابر","حدود ۴٫۵ برابر"]'::jsonb, 3, 'SINGLE', null, 'انرژی استاندارد ≈ ۶۰۰ kN·m/m³ و اصلاح‌شده ≈ ۲۷۰۰ kN·m/m³ است؛ نسبت حدود ۴٫۵.', 'ASTM D698 / D1557'),
  ('civil_supervisor', 'کنترل تراکم', 2, 'وزن مخصوص خشک صحرایی ۱۷٫۱ kN/m³ و حداکثر وزن مخصوص خشک آزمایشگاهی ۱۸٫۰ kN/m³ است. درصد تراکم نسبی چند است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"٪","value":95,"tolPct":1}'::jsonb, 'RC = 17.1 / 18.0 × 100 = 95%', 'ASTM D698 / D1557'),
  ('civil_supervisor', 'کنترل تراکم', 1, 'استاندارد آزمون مخروط ماسه برای تعیین وزن مخصوص صحرایی کدام است؟', '["ASTM D1556","ASTM D4318","ASTM C39","ASTM D2487"]'::jsonb, 0, 'SINGLE', null, 'D1556 روش مخروط ماسه؛ D6938 روش هسته‌ای؛ D4318 حدود آتربرگ؛ C39 مقاومت فشاری استوانه بتن.', 'ASTM D1556'),
  ('civil_supervisor', 'مقاومت بستر', 2, 'در آزمون CBR، بار استاندارد مبنا در نفوذ ۲٫۵ میلی‌متر حدوداً چقدر است؟', '["حدود ۱ kN","حدود ۱۳٫۲ kN","حدود ۵۰ kN","حدود ۲۰۰ kN"]'::jsonb, 1, 'SINGLE', null, 'در ASTM D1883 بار استاندارد در ۲٫۵ mm حدود ۱۳٫۲ kN (۶٫۹ MPa) و در ۵ mm حدود ۲۰ kN است.', 'ASTM D1883 (CBR)'),
  ('civil_supervisor', 'ظرفیت باربری', 3, 'پی نواری روی رس اشباع با چسبندگی c=60 kPa (φ=0) قرار دارد و Nc=5.14 است. ظرفیت باربری مجاز با ضریب ایمنی ۳ (از تأثیر عمق صرف‌نظر شود) چند kPa است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"kPa","value":102.8,"tolPct":2}'::jsonb, 'qult = c·Nc = 60×5.14 = 308.4 kPa؛ qall = 308.4 / 3 ≈ 102.8 kPa', 'Terzaghi / ظرفیت باربری پی‌های سطحی'),
  ('civil_supervisor', 'شیب ترانشه', 2, 'حداکثر شیب مجاز ترانشه در خاک نوع C (OSHA) چقدر است؟', '["۰٫۷۵ افقی به ۱ قائم","۱ افقی به ۱ قائم","۱٫۵ افقی به ۱ قائم","۳ افقی به ۱ قائم"]'::jsonb, 2, 'SINGLE', null, 'OSHA 1926 Subpart P: Type A ≈ ¾:1، Type B = 1:1، Type C = 1½:1.', 'OSHA 29 CFR 1926 Subpart P'),
  ('civil_supervisor', 'خاکریزی خط لوله', 2, 'هدف از بستر و پوشش اولیهٔ (Padding) نرم و بدون سنگ‌ریزه‌های تیز دور لوله در ترانشه چیست؟', '["افزایش مقاومت الکتریکی بین لوله و خاک","کاهش دمای گاز در خط","افزایش وزن لوله برای جلوگیری از جابه‌جایی","محافظت از پوشش لوله و توزیع یکنواخت بار"]'::jsonb, 3, 'SINGLE', null, 'خاک نرم و الک‌شده از ضربه سنگ‌ها به پوشش جلوگیری می‌کند و تکیه‌گاه یکنواخت می‌دهد.', 'IGS-C-PL / ASME B31.8 – مبحث نصب'),
  ('civil_supervisor', 'سطح آب زیرزمینی', 2, 'در عبور خط لوله از زمین با سطح آب بالا، خطر شناوری (Buoyancy) با کدام اقدام کنترل می‌شود؟', '["وزنهٔ بتنی یا پوشش بتنی (CWC)","افزایش دمای گاز داخل لوله","کاهش ضخامت دیواره‌ی لوله","تخلیه‌ی موقت گاز از خط لوله"]'::jsonb, 0, 'SINGLE', null, 'اگر نیروی شناوری از وزن لوله و خاک روی آن بیشتر شود، لوله شناور می‌شود؛ وزنه یا پوشش بتنی (CWC) این را جبران می‌کند.', 'ASME B31.8 – بخش پایداری لوله'),
  ('civil_supervisor', 'گروت زیر صفحه‌ستون', 2, 'چرا زیر صفحهٔ پایهٔ تجهیزات (Base plate) از گروت غیرانقباضی استفاده می‌شود؟', '["برای افزایش سرعت گیرش بتن فونداسیون","برای تماس کامل و انتقال یکنواخت بار","برای کاهش وزن تجهیز روی فونداسیون","برای تغییر رنگ و ظاهر سطح بتن"]'::jsonb, 1, 'SINGLE', null, 'گروت غیرانقباضی فضای زیر صفحه را بدون حفره پر می‌کند و انتقال بار و تراز را تضمین می‌کند.', 'API 686 / ACI 351.1R (Grouting)')
) as v(job_role, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref)
where not exists (select 1 from comp_mcq_questions e where e.job_role = v.job_role and e.stem_fa = v.stem_fa);
